import{_ as i,l as s,o as t,c as l,v as e,p as n,x as r,d as p,i as d,S as T}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"NTP","description":"","frontmatter":{"title":"NTP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ntp.md","filePath":"cs/ntp.md","lastUpdated":1789023840000}'),c={name:"cs/ntp.md"};function h(P,a,m,_,u,E){const o=s("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="ntp" tabindex="-1">NTP <a class="header-anchor" href="#ntp" aria-label="Permalink to &quot;NTP&quot;">​</a></h1><div class="epigraph"><p>NTP 用四时间戳估计往返与偏移，把主机时钟循向更上层的源；分层 stratum 防止环，精度到毫秒级常见。</p><footer>—— 据 RFC 5905 NTPv4；Mills, Computer Network Time Synchronization 整理</footer></div><p><a href="/cs/dnssec">DNSSEC</a> 与 <a href="/cs/http-tls-entry">TLS</a> 要合理时钟。<a href="/cs/ssh-protocol">上一课</a> 的证书也要。缺口是 <strong>NTP</strong>：偏移估计、层级、不是 GPS 微秒。本课不把 PTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机晶振漂。NTP：客户发 t1，服务器收 t2 发 t3，客户收 t4，偏移 θ≈((t2−t1)+(t3−t4))/2，延迟 δ=(t4−t1)−(t3−t2)。选多层源滤波。Stratum 1 近原子钟，往下递增。认证可用对称钥或 NTS（点名）。被劫持的时间源能搞垮 DNSSEC 与票据。</p><p>不要把 <code>date</code> 命令当协议。</p><p><span class="marginnote">RFC 5905。闰秒处理是边界。本课不把钟控环 PID 写完。</span></p><h3 id="毫秒级驯服" tabindex="-1">毫秒级驯服 <a class="header-anchor" href="#毫秒级驯服" aria-label="Permalink to &quot;毫秒级驯服&quot;">​</a></h3><p>四时间戳假设路径对称。多源防单点。时间错会搞垮 DNSSEC 与 PAWS。公网单台 NTP 不够。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：四时间戳 → 偏移。对照 ping：都用 RTT，NTP 要对称假设。非对称路径（卫星、流量工程）使 θ 偏。</p>',11)),(t(),n(T,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E5%AE%A2%E6%88%B7%E5%8F%91%22%5D%20--%3E%20T2%5B%22%E6%9C%8D%E5%8A%A1%E6%94%B6%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E6%9C%8D%E5%8A%A1%E5%8F%91%22%5D%0A%20%20T3%20--%3E%20T4%5B%22%E5%AE%A2%E6%88%B7%E6%94%B6%22%5D%0A%20%20T4%20--%3E%20OFF%5B%22%E4%BC%B0%E5%81%8F%E7%A7%BB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数据中心用本地 stratum，减公网 RTT 噪声。防火墙放 123/UDP。DoS 放大曾是 NTP 单播/monlist 问题，当代应关。与 BDP 无关直接，但时间错会导致 TCP 时间戳 PAWS 误杀。</p><p>VM 热迁移后时钟跳，要重新驯服，接 OS 补层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 NTS 握手全文。PTP 是下一课。后课默认：NTP 毫秒级驯服；路径不对称是误差源。</p><p>只信一台公网 NTP 是单点。</p><p>上一课留下的缺口在本课收口；「NTP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ptp-precision-time">PTP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四时间戳估偏移与延迟。</li><li>Stratum 分层；要多源。</li><li>安全：认证，关放大。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 5905；Mills。</li></ul>',10))])}const f=i(c,[["render",h]]);export{N as __pageData,f as default};
